const sports=[['Aquatics','aquatics'],['Athletics','athletics'],['Badminton','badminton'],['Basketball','basketball'],['Board games','boardgames'],['Cricket','cricket'],['Football','football'],['Hockey','hockey'],['Indian games','indiangames'],['Lawn tennis','tennis'],['Squash','squash'],['Table tennis','tabletennis'],['Volleyball','volleyball'],['Weightlifting','weightlifting'],['Adventure club','adventureclub'],['Dark Knight Chess Club','chess'],["Rubik’s club",'rubik'],['Ultimate frisbee','frisbee'],['Yogastha','yoga']];
const directory=document.querySelector('#sport-directory');for(const [name,slug]of sports){const a=document.createElement('a');a.href=`sports/${slug}.html`;a.textContent=name;const arrow=document.createElement('span');arrow.textContent='↗';arrow.setAttribute('aria-hidden','true');a.append(arrow);directory.append(a);}
